/*
 * test_proto.c - offline tests for bf63112_proto.c.
 *
 * Builds every frame from tests/vectors.h (generated by
 * tests/generate_fixtures.py), which are the exact bytes the Python reference
 * implementation produces, and then parses them back.  Also covers the
 * rejection paths, the stream scanner and GET_IMG reassembly.
 *
 * Build & run:  make -C tools/fingerprint proto-test   (see README.md)
 */

#include "bf63112_proto.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vectors.h"

static int failures;
static int checks;

#define CHECK(cond)                                                           \
  do {                                                                        \
    checks++;                                                                 \
    if (!(cond))                                                              \
      {                                                                       \
        failures++;                                                           \
        fprintf (stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);      \
      }                                                                       \
  } while (0)

#define CHECK_EQ_INT(actual, expected)                                        \
  do {                                                                        \
    long long a_ = (long long) (actual);                                       \
    long long e_ = (long long) (expected);                                     \
    checks++;                                                                 \
    if (a_ != e_)                                                             \
      {                                                                       \
        failures++;                                                           \
        fprintf (stderr, "FAIL %s:%d: %s == %lld, expected %lld\n",           \
                 __FILE__, __LINE__, #actual, a_, e_);                        \
      }                                                                       \
  } while (0)

static int
hex_nibble (char c)
{
  if (c >= '0' && c <= '9')
    return c - '0';
  if (c >= 'a' && c <= 'f')
    return c - 'a' + 10;
  if (c >= 'A' && c <= 'F')
    return c - 'A' + 10;
  return -1;
}

static size_t
hex_decode (const char *hex, unsigned char *out, size_t out_size)
{
  size_t len = strlen (hex) / 2;
  size_t i;

  if (strlen (hex) % 2 != 0 || len > out_size)
    return 0;
  for (i = 0; i < len; i++)
    {
      int hi = hex_nibble (hex[2 * i]);
      int lo = hex_nibble (hex[2 * i + 1]);
      if (hi < 0 || lo < 0)
        return 0;
      out[i] = (unsigned char) ((hi << 4) | lo);
    }
  return len;
}

static void
test_crc (void)
{
  static const unsigned char check[] = "123456789";
  unsigned char buf[8];
  size_t i;

  CHECK_EQ_INT (bf63112_crc32 (check, 9), 0xCBF43926u);
  CHECK_EQ_INT (bf63112_crc32 (NULL, 0), 0);
  for (i = 0; i < sizeof (buf); i++)
    buf[i] = (unsigned char) (i * 37 + 1);
  CHECK (bf63112_crc32 (buf, sizeof (buf)) != 0);
}

static void
test_vectors (void)
{
  size_t v;

  for (v = 0; v < BF63112_VECTOR_COUNT; v++)
    {
      const struct bf63112_test_vector *vec = &bf63112_vectors[v];
      unsigned char expected[1024];
      unsigned char frame[1024];
      size_t expected_len, frame_len;
      struct bf63112_frame parsed;

      expected_len = hex_decode (vec->frame_hex, expected, sizeof (expected));
      CHECK_EQ_INT (expected_len, vec->frame_len);
      CHECK_EQ_INT (bf63112_length_field (vec->data_len), vec->length_field);
      CHECK_EQ_INT (bf63112_frame_size (vec->data_len), vec->frame_len);

      memset (frame, 0xA5, sizeof (frame));
      frame_len = bf63112_build_frame (vec->opcode, vec->phase, vec->status,
                                       vec->arg, vec->data, vec->data_len,
                                       frame, sizeof (frame));
      CHECK_EQ_INT (frame_len, vec->frame_len);
      CHECK_EQ_INT (memcmp (frame, expected, expected_len), 0);
      CHECK_EQ_INT (bf63112_crc32 (frame, frame_len - 4), vec->crc);

      CHECK_EQ_INT (bf63112_parse_frame (frame, frame_len, &parsed),
                    BF63112_PARSE_OK);
      CHECK_EQ_INT (parsed.opcode, vec->opcode);
      CHECK_EQ_INT (parsed.phase, vec->phase);
      CHECK_EQ_INT (parsed.status, vec->status);
      CHECK_EQ_INT (parsed.arg, vec->arg);
      CHECK_EQ_INT (parsed.data_len, vec->data_len);
      CHECK_EQ_INT (parsed.length_field, vec->length_field);
      CHECK_EQ_INT (parsed.crc, vec->crc);
      CHECK_EQ_INT (parsed.size, vec->frame_len);
      if (vec->data_len > 0)
        CHECK_EQ_INT (memcmp (parsed.data, vec->data, vec->data_len), 0);

      /* scanning must find the same frame behind junk */
      {
        unsigned char stream[1200];
        size_t offset = 0;
        struct bf63112_frame scanned;
        memset (stream, 0xFF, 8);
        memcpy (stream + 8, frame, frame_len);
        memset (stream + 8 + frame_len, 0x00, 16);
        CHECK_EQ_INT (bf63112_scan_frame (stream, 8 + frame_len + 16,
                                          &offset, &scanned),
                      BF63112_SCAN_OK);
        CHECK_EQ_INT (offset, 8);
        CHECK_EQ_INT (scanned.opcode, vec->opcode);
      }
    }
}

static void
test_rejects (void)
{
  unsigned char frame[128];
  unsigned char bad[128];
  size_t len, i;
  struct bf63112_frame parsed;

  len = bf63112_build_frame (BF63112_OP_QUERY_SENSOR_INFO, 0, 0, 0,
                             NULL, 0, frame, sizeof (frame));
  CHECK_EQ_INT (len, 41);
  CHECK_EQ_INT (bf63112_build_frame (0xA1, 0, 0, 0, NULL, 0, NULL, 0), 0);
  CHECK_EQ_INT (bf63112_build_frame (0xA1, 0, 0, 0, NULL, 0, frame, 40), 0);

  /* every truncation must be rejected */
  for (i = 0; i < len; i++)
    CHECK (bf63112_parse_frame (frame, i, &parsed) != BF63112_PARSE_OK);

  /* trailing garbage: length field disagrees with the buffer */
  memcpy (bad, frame, len);
  bad[len] = 0x00;
  CHECK_EQ_INT (bf63112_parse_frame (bad, len + 1, &parsed),
                BF63112_PARSE_BAD_LENGTH);

  /* bad start byte */
  memcpy (bad, frame, len);
  bad[0] = 0x55;
  CHECK_EQ_INT (bf63112_parse_frame (bad, len, &parsed),
                BF63112_PARSE_BAD_SOF);

  /* bad magic */
  memcpy (bad, frame, len);
  bad[BF63112_OFF_MAGIC] = 0x4D;
  {
    uint32_t crc = bf63112_crc32 (bad, len - 4);
    bad[len - 4] = (unsigned char) (crc & 0xFF);
    bad[len - 3] = (unsigned char) ((crc >> 8) & 0xFF);
    bad[len - 2] = (unsigned char) ((crc >> 16) & 0xFF);
    bad[len - 1] = (unsigned char) ((crc >> 24) & 0xFF);
  }
  CHECK_EQ_INT (bf63112_parse_frame (bad, len, &parsed),
                BF63112_PARSE_BAD_MAGIC);

  /* data_len larger than the command block holds */
  memcpy (bad, frame, len);
  bad[BF63112_OFF_DATA_LEN] = 7;       /* block 16 -> capacity 6 */
  {
    uint32_t crc = bf63112_crc32 (bad, len - 4);
    bad[len - 4] = (unsigned char) (crc & 0xFF);
    bad[len - 3] = (unsigned char) ((crc >> 8) & 0xFF);
    bad[len - 2] = (unsigned char) ((crc >> 16) & 0xFF);
    bad[len - 1] = (unsigned char) ((crc >> 24) & 0xFF);
  }
  CHECK_EQ_INT (bf63112_parse_frame (bad, len, &parsed),
                BF63112_PARSE_BAD_DATA_LEN);

  /* every single-byte mutation must be rejected */
  for (i = 0; i < len; i++)
    {
      memcpy (bad, frame, len);
      bad[i] ^= 0xFF;
      CHECK (bf63112_parse_frame (bad, len, &parsed) != BF63112_PARSE_OK);
    }

  /* CRC mismatch is reported as such */
  memcpy (bad, frame, len);
  bad[len - 1] ^= 0xFF;
  CHECK_EQ_INT (bf63112_parse_frame (bad, len, &parsed),
                BF63112_PARSE_BAD_CRC);
}

static void
test_scan (void)
{
  unsigned char frame_a[128], frame_b[128], stream[512];
  unsigned char bad[128];
  size_t len_a, len_b, offset = 0;
  struct bf63112_frame frame;

  len_a = bf63112_build_frame (0xA1, 0, 0, 0, NULL, 0,
                               frame_a, sizeof (frame_a));
  len_b = bf63112_build_frame (0xC2, 0, 0, 0x1234, NULL, 0,
                               frame_b, sizeof (frame_b));

  /* junk + two frames + zeros */
  memset (stream, 0xFF, 5);
  memcpy (stream + 5, frame_a, len_a);
  memcpy (stream + 5 + len_a, frame_b, len_b);
  memset (stream + 5 + len_a + len_b, 0x00, 33);
  CHECK_EQ_INT (bf63112_scan_frame (stream, 5 + len_a + len_b + 33,
                                    &offset, &frame),
                BF63112_SCAN_OK);
  CHECK_EQ_INT (offset, 5);
  CHECK_EQ_INT (frame.opcode, 0xA1);

  /* scan from the second frame */
  CHECK_EQ_INT (bf63112_scan_frame (stream + 5 + len_a,
                                    len_b + 33, &offset, &frame),
                BF63112_SCAN_OK);
  CHECK_EQ_INT (offset, 0);
  CHECK_EQ_INT (frame.opcode, 0xC2);

  /* all junk */
  memset (stream, 0xFF, 64);
  CHECK_EQ_INT (bf63112_scan_frame (stream, 64, &offset, &frame),
                BF63112_SCAN_NO_FRAME);

  /* truncated candidate */
  memcpy (stream, frame_a, len_a - 3);
  CHECK_EQ_INT (bf63112_scan_frame (stream, len_a - 3, &offset, &frame),
                BF63112_SCAN_TRUNCATED);

  /* corrupt frame then a good one */
  memcpy (bad, frame_a, len_a);
  bad[len_a - 1] ^= 0xFF;
  memcpy (stream, bad, len_a);
  memcpy (stream + len_a, frame_b, len_b);
  CHECK_EQ_INT (bf63112_scan_frame (stream, len_a + len_b, &offset, &frame),
                BF63112_SCAN_OK);
  CHECK_EQ_INT (offset, len_a);
  CHECK_EQ_INT (frame.opcode, 0xC2);

  /* only corrupt bytes */
  memcpy (stream, bad, len_a);
  CHECK_EQ_INT (bf63112_scan_frame (stream, len_a, &offset, &frame),
                BF63112_SCAN_CORRUPT);

  /* empty buffer */
  CHECK_EQ_INT (bf63112_scan_frame (NULL, 0, &offset, &frame),
                BF63112_SCAN_NO_FRAME);
}

static void
test_image (void)
{
  unsigned char image[64];
  unsigned char buf[64];
  unsigned char header_payload[9];
  unsigned char chunk[16];
  unsigned char chunk_sum;
  struct bf63112_image_header header;
  struct bf63112_image_assembler asm_;
  size_t i;

  for (i = 0; i < sizeof (image); i++)
    image[i] = (unsigned char) ((i * 7) % 256);

  header.status = 0;
  header.total_bytes = sizeof (image);
  header.byte_sum = bf63112_sum8 (image, sizeof (image));
  CHECK_EQ_INT (bf63112_image_header_build (&header, header_payload,
                                            sizeof (header_payload)), 9);

  {
    struct bf63112_image_header parsed;
    CHECK_EQ_INT (bf63112_image_header_parse (header_payload, 9, &parsed),
                  BF63112_IMAGE_OK);
    CHECK_EQ_INT (parsed.total_bytes, sizeof (image));
    CHECK_EQ_INT (parsed.byte_sum, header.byte_sum);
    CHECK_EQ_INT (bf63112_image_header_parse (header_payload, 8, &parsed),
                  BF63112_IMAGE_ERR_HEADER);
  }

  bf63112_image_init (&asm_, buf, sizeof (buf), &header,
                      BF63112_MAX_IMAGE_CHUNK);
  for (i = 0; i < sizeof (image); i += 16)
    {
      memcpy (chunk, image + i, 16);
      CHECK_EQ_INT (bf63112_image_add (&asm_, chunk, 16, NULL),
                    BF63112_IMAGE_OK);
    }
  CHECK_EQ_INT (asm_.received, sizeof (image));
  CHECK_EQ_INT (bf63112_image_finish (&asm_), BF63112_IMAGE_OK);
  CHECK_EQ_INT (memcmp (buf, image, sizeof (image)), 0);

  /* incomplete */
  bf63112_image_init (&asm_, buf, sizeof (buf), &header, BF63112_MAX_IMAGE_CHUNK);
  bf63112_image_add (&asm_, image, 16, NULL);
  CHECK_EQ_INT (bf63112_image_finish (&asm_), BF63112_IMAGE_ERR_SHORT);

  /* global sum mismatch */
  header.byte_sum ^= 0x01;
  bf63112_image_init (&asm_, buf, sizeof (buf), &header, BF63112_MAX_IMAGE_CHUNK);
  bf63112_image_add (&asm_, image, sizeof (image), NULL);
  CHECK_EQ_INT (bf63112_image_finish (&asm_), BF63112_IMAGE_ERR_SUM);
  header.byte_sum ^= 0x01;

  /* chunk above the ceiling */
  bf63112_image_init (&asm_, buf, sizeof (buf), &header, 8);
  CHECK_EQ_INT (bf63112_image_add (&asm_, chunk, 16, NULL),
                BF63112_IMAGE_ERR_OVERSIZE);
  CHECK_EQ_INT (bf63112_image_add (&asm_, chunk, 8, NULL), BF63112_IMAGE_OK);

  /* run past the announced total */
  {
    struct bf63112_image_header small = { 0, 10, 0 };
    bf63112_image_init (&asm_, buf, sizeof (buf), &small,
                        BF63112_MAX_IMAGE_CHUNK);
    CHECK_EQ_INT (bf63112_image_add (&asm_, chunk, 8, NULL), BF63112_IMAGE_OK);
    CHECK_EQ_INT (bf63112_image_add (&asm_, chunk, 8, NULL),
                  BF63112_IMAGE_ERR_OVERRUN);
  }

  /* optional per-chunk sum */
  bf63112_image_init (&asm_, buf, sizeof (buf), &header, BF63112_MAX_IMAGE_CHUNK);
  chunk_sum = bf63112_sum8 (image, 16);
  CHECK_EQ_INT (bf63112_image_add (&asm_, image, 16, &chunk_sum),
                BF63112_IMAGE_OK);
  chunk_sum ^= 0x01;
  CHECK_EQ_INT (bf63112_image_add (&asm_, image + 16, 16, &chunk_sum),
                BF63112_IMAGE_ERR_CHUNK_SUM);
}

static void
test_tables (void)
{
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_ENROLL_FINGERPRINT));
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_REMOVE_FINGERPRINT));
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_JTAG_CONTROL));
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_RESTORE_MCU));
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_UPDATE_FIRMWARE));
  CHECK (bf63112_opcode_is_destructive (BF63112_OP_FW_WORK_MODE_SWITCH));
  CHECK (!bf63112_opcode_is_destructive (BF63112_OP_QUERY_SENSOR_INFO));
  CHECK (!bf63112_opcode_is_destructive (BF63112_OP_GET_IMG_DATA));
  CHECK (strcmp (bf63112_opcode_name (BF63112_OP_QUERY_SENSOR_INFO),
                 "CMD_QUERY_SENSOR_INFO") == 0);
  CHECK (bf63112_opcode_name (0x00) == NULL);
}

int
main (void)
{
  test_crc ();
  test_vectors ();
  test_rejects ();
  test_scan ();
  test_image ();
  test_tables ();

  if (failures != 0)
    {
      fprintf (stderr, "%d/%d checks FAILED\n", failures, checks);
      return 1;
    }
  printf ("ok: %d checks, %zu vectors\n", checks, (size_t) BF63112_VECTOR_COUNT);
  return 0;
}
